"""Descriptive statistics for small lists of numbers."""


def mean(values):
    """Arithmetic mean using true division, so fractions survive.

    An empty list raises ValueError.
    """
    if not values:
        raise ValueError("mean of empty list")
    return sum(values) / len(values)


def median(values):
    """Middle value; for an even count, the midpoint of the two middle
    values. The input order does not matter. An empty list raises
    ValueError."""
    data = sorted(values)
    if not data:
        raise ValueError("median of empty list")
    mid = len(data) // 2
    if len(data) % 2 == 1:
        return data[mid]
    return (data[mid - 1] + data[mid]) / 2


def value_range(values):
    """Largest minus smallest. An empty list raises ValueError."""
    if not values:
        raise ValueError("range of empty list")
    return max(values) - min(values)

