from __future__ import annotations
from typing import List, Optional, Tuple

from .board import Board


def legal_moves(board: Board, color: str) -> List[Tuple[Tuple[int, int], Tuple[int, int], Optional[Tuple[int, int]]]]:
    """Return all legal moves for *color* on *board*.

    Each move is (from_sq, to_sq, captured) where captured is None
    for a plain step or the (col, row) of the jumped piece for a
    capture.  If any capture exists, only captures are returned.
    """
    moves: List[Tuple[Tuple[int, int], Tuple[int, int], Optional[Tuple[int, int]]]] = []
    captures: List[Tuple[Tuple[int, int], Tuple[int, int], Tuple[int, int]]] = []

    for row in range(8):
        for col in range(8):
            piece = board.grid[row][col]
            if piece is None or piece.color != color:
                continue

            directions = _directions(piece)
            for dc, dr in directions:
                # plain step
                nc, nr = col + dc, row + dr
                if 0 <= nc < 8 and 0 <= nr < 8 and board.grid[nr][nc] is None:
                    moves.append(((col, row), (nc, nr), None))

                # capture
                mc, mr = col + 2 * dc, row + 2 * dr
                if 0 <= mc < 8 and 0 <= mr < 8:
                    mid = board.grid[mr][mc]
                    if mid is not None and mid.color != color and board.grid[nr][nc] is None:
                        captures.append(((col, row), (mc, mr), (col + dc, row + dr)))

    return captures if captures else moves


def apply_move(board: Board, move: Tuple[Tuple[int, int], Tuple[int, int], Optional[Tuple[int, int]]]) -> None:
    """Execute *move* on *board* without validating legality."""
    (fc, fr), (tc, tr), captured = move
    piece = board.grid[fr][fc]
    board.grid[fr][fc] = None
    if captured is not None:
        board.grid[captured[1]][captured[0]] = None
    board.grid[tr][tc] = piece
    if not piece.king:
        if piece.color == "red" and tr == 7:
            piece.king = True
        elif piece.color == "black" and tr == 0:
            piece.king = True


def winner(board: Board) -> Optional[str]:
    """Return 'red', 'black', or None."""
    red_has = False
    black_has = False
    for row in range(8):
        for col in range(8):
            p = board.grid[row][col]
            if p is None:
                continue
            if p.color == "red":
                red_has = True
            else:
                black_has = True
    if not red_has:
        return "black"
    if not black_has:
        return "red"
    if legal_moves(board, "red") or legal_moves(board, "black"):
        return None
    return "red" if legal_moves(board, "red") else "black"


def _directions(piece) -> List[Tuple[int, int]]:
    if piece.king:
        return [(-1, -1), (-1, 1), (1, -1), (1, 1)]
    if piece.color == "red":
        return [(-1, 1), (1, 1)]
    return [(-1, -1), (1, -1)]

