class Piece:
    """A checkers piece."""

    def __init__(self, color: str, king: bool = False) -> None:
        self.color = color
        self.king = king


class Board:
    """8x8 American checkers board."""

    def __init__(self) -> None:
        self.grid: list[list[Piece | None]] = [[None] * 8 for _ in range(8)]
        self._init_pieces()

    def _init_pieces(self) -> None:
        for row in range(8):
            for col in range(8):
                if (col + row) % 2 == 1:
                    if row < 3:
                        self.grid[row][col] = Piece("red")
                    elif row > 4:
                        self.grid[row][col] = Piece("black")

    def legal_moves(self, color: str) -> list[tuple[tuple[int, int], tuple[int, int], tuple[int, int] | None]]:
        """Return legal moves for *color*.

        Each move is (from_sq, to_sq, captured) where
        from_sq/to_sq are (col, row) and captured is None or
        the (col, row) of the jumped enemy piece.
        """
        captures = []
        steps = []
        for row in range(8):
            for col in range(8):
                piece = self.grid[row][col]
                if piece is None or piece.color != color:
                    continue
                for dr, dc in self._directions(piece):
                    nr, nc = row + dr, col + dc
                    if not self._on_board(nr, nc):
                        continue
                    if self.grid[nr][nc] is None:
                        steps.append(((col, row), (nc, nr), None))
                    else:
                        enemy = self.grid[nr][nc]
                        if enemy.color != color:
                            jr, jc = nr + dr, nc + dc
                            if self._on_board(jr, jc) and self.grid[jr][jc] is None:
                                captures.append(((col, row), (jc, jr), (nc, nr)))
        if captures:
            return captures
        return steps

    def apply_move(self, move: tuple[tuple[int, int], tuple[int, int], tuple[int, int] | None]) -> None:
        """Execute *move* without validating legality."""
        (fc, fr), (tc, tr), captured = move
        piece = self.grid[fr][fc]
        self.grid[fr][fc] = None
        if captured is not None:
            cc, cr = captured
            self.grid[cr][cc] = None
        if piece.color == "red" and tr == 7:
            piece.king = True
        elif piece.color == "black" and tr == 0:
            piece.king = True
        self.grid[tr][tc] = piece

    def winner(self) -> str | None:
        """Return 'red', 'black', or None."""
        red_has = False
        black_has = False
        for row in range(8):
            for col in range(8):
                p = self.grid[row][col]
                if p is None:
                    continue
                if p.color == "red":
                    red_has = True
                else:
                    black_has = True
        if not red_has:
            return "black"
