        if self.legal_moves("red"):
            return None
        if self.legal_moves("black"):
            return None
        return "red" if red_has else "black"

    def _directions(self, piece: Piece) -> list[tuple[int, int]]:
        if piece.king:
            return [(-1, -1), (-1, 1), (1, -1), (1, 1)]
        if piece.color == "red":
            return [(-1, -1), (-1, 1)]
