def _fresh_board() -> list[list[Piece | None]]:
    """Return a fresh 8x8 board grid."""
    grid: list[list[Piece | None]] = [[None] * 8 for _ in range(8)]
    for row in range(8):
        for col in range(8):
            if (col + row) % 2 == 1:
                if row < 3:
                    grid[row][col] = Piece("red")
                elif row > 4:
                    grid[row][col] = Piece("black")
    return grid


class Board:
    """American checkers board state."""

    def __init__(self) -> None:
        self.grid = _fresh_board()

    def legal_moves(self, color: str) -> list[tuple[tuple[int, int], tuple[int, int], tuple[int, int] | None]]:
        """Return legal moves for *color*.

        Each move is (from_sq, to_sq, captured) where
        from_sq/to_sq are (col, row) and captured is the jumped
        square or None.
        """
        moves: list[tuple[tuple[int, int], tuple[int, int], tuple[int, int] | None]] = []
        for row in range(8):
            for col in range(8):
                piece = self.grid[row][col]
                if piece is None or piece.color != color:
                    continue
                for dr, dc in self._directions(piece):
                    nr, nc = row + dr, col + dc
                    if not self._on_board(nr, nc):
                        continue
                    if self.grid[nr][nc] is None:
                        moves.append(((col, row), (nc, nr), None))
                    else:
                        enemy = self.grid[nr][nc]
                        if enemy.color != color:
                            jr, jc = nr + dr, nc + dc
                            if self._on_board(jr, jc) and self.grid[jr][jc] is None:
                                moves.append(((col, row), (jc, jr), (nc, nr)))
        has_capture = any(m[2] is not None for m in moves)
        if has_capture:
            return [m for m in moves if m[2] is not None]
        return moves

    def apply_move(self, move: tuple[tuple[int, int], tuple[int, int], tuple[int, int] | None]) -> None:
        """Execute *move* without validating legality."""
        (fc, fr), (tc, tr), captured = move
        piece = self.grid[fr][fc]
        self.grid[fr][fc] = None
        if captured is not None:
            cc, cr = captured
            self.grid[cr][cc] = None
        if piece.color == "red" and tr == 7:
            piece = Piece("red", king=True)
        elif piece.color == "black" and tr == 0:
            piece = Piece("black", king=True)
        self.grid[tr][tc] = piece

    def winner(self) -> str | None:
        """Return the winner color or None if the game is ongoing."""
        red_has = False
        black_has = False
        for row in range(8):
            for col in range(8):
                p = self.grid[row][col]
                if p is None:
                    continue
                if p.color == "red":
                    red_has = True
                else:
                    black_has = True
        if not red_has:
            return "black"
        if not black_has:
            return "red"
        if not self.legal_moves("red"):
            return "black"
        if not self.legal_moves("black"):
            return "red"
        return None

    def _directions(self, piece: Piece) -> list[tuple[int, int]]:
        if piece.king:
