import json
import time

from . import store


def write_blob(root, data) -> str:
    return store.put_object(root, data)


def read_blob(root, sha) -> bytes:
    return store.get_object(root, sha)


def make_tree(root, entries) -> str:
    canon = []
    for entry in entries:
        canon.append({
            "name": entry["name"],
            "type": entry["type"],
            "mode": entry["mode"],
            "hash": entry["hash"],
            "size": entry["size"],
        })
    canon.sort(key=lambda e: e["name"])
    lines = [json.dumps(e, sort_keys=True, separators=(",", ":")) for e in canon]
    data = "\n".join(lines).encode("utf-8")
    return store.put_object(root, data)


def read_tree(root, sha) -> list:
    data = store.get_object(root, sha)
    text = data.decode("utf-8")
    entries = []
    for line in text.split("\n"):
        if line == "":
            continue
        entries.append(json.loads(line))
    entries.sort(key=lambda e: e["name"])
    return entries


def write_commit(root, tree_sha, parents, message, author="main", agent=None, ts=None) -> str:
    if ts is None:
        ts = int(time.time())
    doc = {
        "tree": tree_sha,
        "parents": list(parents),
        "message": message,
        "author": author,
        "agent": agent,
        "ts": ts,
    }
    data = json.dumps(doc, sort_keys=True, separators=(",", ":")).encode("utf-8")
    return store.put_object(root, data)


def read_commit(root, sha) -> dict:
    data = store.get_object(root, sha)
    return json.loads(data.decode("utf-8"))

