import hashlib
import os
import zlib


class CorruptObject(Exception):
    pass


def hash_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def obj_path(root: str, sha: str) -> str:
    return root + "/.keel/objects/" + sha[:2] + "/" + sha


def put_object(root: str, data: bytes) -> str:
    sha = hash_bytes(data)
    path = obj_path(root, sha)
    if os.path.exists(path):
        return sha
    shard = os.path.dirname(path)
    os.makedirs(shard, exist_ok=True)
    tmp = os.path.join(shard, ".tmp-" + sha)
    with open(tmp, "wb") as f:
        f.write(zlib.compress(data))
        f.flush()
        os.fsync(f.fileno())
    os.replace(tmp, path)
    return sha


def get_object(root: str, sha: str) -> bytes:
    path = obj_path(root, sha)
    with open(path, "rb") as f:
        raw = f.read()
    data = zlib.decompress(raw)
    if hash_bytes(data) != sha:
        raise CorruptObject(f"object {sha} failed hash verification")
    return data


def has_object(root: str, sha: str) -> bool:
    return os.path.exists(obj_path(root, sha))


def iter_objects(root: str):
    objects_dir = root + "/.keel/objects"
    if not os.path.isdir(objects_dir):
        return
    for shard in sorted(os.listdir(objects_dir)):
        shard_dir = os.path.join(objects_dir, shard)
        if not os.path.isdir(shard_dir):
            continue
        for name in sorted(os.listdir(shard_dir)):
            full = os.path.join(shard_dir, name)
            if os.path.isfile(full):
                yield shard + name

