import json
import time

from . import store


def write_blob(root: str, data: bytes) -> str:
    """Store a blob and return its sha."""
    return store.put_object(root, data)


def read_blob(root: str, sha: str) -> bytes:
    """Read a blob's bytes by sha."""
    return store.get_object(root, sha)


def make_tree(root: str, entries: list[dict]) -> str:
    """Canonically serialize entries and store them as a tree object."""
    canon = []
    for entry in entries:
        canon.append({
            "name": entry["name"],
            "type": entry["type"],
            "mode": entry["mode"],
            "hash": entry["hash"],
            "size": entry["size"],
        })
    canon.sort(key=lambda e: e["name"])
    lines = [
        json.dumps(e, sort_keys=True, separators=(",", ":"))
        for e in canon
    ]
    data = "\n".join(lines).encode("utf-8")
    return store.put_object(root, data)


def read_tree(root: str, sha: str) -> list[dict]:
    """Parse a tree object back into its entry list, sorted by name."""
    data = store.get_object(root, sha)
    text = data.decode("utf-8")
    entries = []
    for line in text.split("\n"):
        if line == "":
            continue
        entries.append(json.loads(line))
    entries.sort(key=lambda e: e["name"])
    return entries


def write_commit(root: str, tree_sha: str, parents: list[str], message: str,
                 author: str = "main", agent=None, ts=None) -> str:
    """Store a commit document and return its content-addressed id."""
    if ts is None:
        ts = int(time.time())
    doc = {
        "tree": tree_sha,
        "parents": list(parents),
        "message": message,
        "author": author,
        "agent": agent,
        "ts": ts,
    }
    data = json.dumps(doc, sort_keys=True, separators=(",", ":")).encode("utf-8")
    return store.put_object(root, data)


def read_commit(root: str, sha: str) -> dict:
    """Read a commit document by sha."""
    data = store.get_object(root, sha)
    return json.loads(data.decode("utf-8"))

